function move(id:string,col:number,dy:number,dx:number,extend=false){const index=visibleIds.indexOf(id),nextCol=col+dx;let nextIndex=index+dy,c=nextCol;if(c>3){c=0;nextIndex++;}if(c<0){c=3;nextIndex--;}nextIndex=Math.max(0,Math.min(visibleIds.length-1,nextIndex));const target={id:visibleIds[nextIndex],col:c};if(!target.id)return;if(extend){range={start:range?.start??{id,col},end:target};}else range={start:target,end:target};focus=target;if(view.paged&&Math.floor(nextIndex/100)!==(view.page??0)){view.page=Math.floor(nextIndex/100);rebuild();}if(pinnedMove&&target.id!==pinnedMove){pinnedMove=undefined;$('#move-context').hidden=true;}const item=flat.findIndex(e=>e.kind==='row'&&e.id===target.id);const viewport=$('#viewport');if(item*ROW<viewport.scrollTop)viewport.scrollTop=item*ROW;else if((item+1)*ROW>viewport.scrollTop+viewport.clientHeight)viewport.scrollTop=(item+1)*ROW-viewport.clientHeight;renderWindow();const input=nodes.get('row:'+target.id)?.querySelector<HTMLInputElement>(`[data-col="${c}"]`);navigationFocus=true;input?.focus({preventScroll:true});navigationFocus=false;paintRange();persistView(false);}
function key(e:KeyboardEvent,id:string,col:number){if(e.isComposing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();finishEditor();historyAction(e.shiftKey);return;}if(e.key==='Escape'){e.preventDefault();finishEditor(true);return;}if(e.key==='Tab'||e.key==='Enter'){e.preventDefault();finishEditor();move(id,col,e.key==='Enter'?(e.shiftKey?-1:1):0,e.key==='Tab'?(e.shiftKey?-1:1):0);return;}if(e.key.startsWith('Arrow')&&!editor?.editing){e.preventDefault();finishEditor();move(id,col,e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0,e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0,e.shiftKey);return;}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&editor)editor.editing=true;}
function copyText(){const r=range??(focus?{start:focus,end:focus}:undefined);if(!r)return '';const a=visibleIds.indexOf(r.start.id),b=visibleIds.indexOf(r.end.id);return visibleIds.slice(Math.min(a,b),Math.max(a,b)+1).map(id=>store.rows.get(id)!.packs.slice(Math.min(r.start.col,r.end.col),Math.max(r.start.col,r.end.col)+1).map(v=>v===null?'':String(v)).join('\t')).join('\n');}
