function modal(title:string,html:string,action?:()=>unknown|Promise<unknown>,label='Apply',anchor?:HTMLElement){const dialog=$<HTMLDialogElement>('#dialog');dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><h2>${esc(title)}</h2><button class="close" value="cancel" aria-label="Close dialog">×</button></div><div class="dialog-body">${html}</div><p id="dialog-error" role="alert"></p><div class="dialog-footer"><button value="cancel">${anchor?'Close':'Cancel'}</button>${action?`<button type="button" id="dialog-apply" class="primary">${esc(label)}</button>`:''}</div></form>`;if(action)$('#dialog-apply').onclick=async()=>{try{await action();dialog.close();if(pinnedMove&&focus)nodes.get('row:'+focus.id)?.querySelector<HTMLInputElement>(`[data-col="${focus.col}"]`)?.focus({preventScroll:true});}catch(error){$('#dialog-error').textContent=(error as Error).message;}};dialog.classList.toggle('dropdown',!!anchor);dialog.removeAttribute('style');if(anchor){dialog.style.width=anchor.id==='vendors'?'360px':'720px';dialog.show();const rect=anchor.getBoundingClientRect();dialog.style.left=Math.max(12,Math.min(rect.left,innerWidth-dialog.offsetWidth-12))+'px';dialog.style.top=(rect.bottom+dialog.offsetHeight+8<innerHeight?rect.bottom+6:Math.max(12,rect.top-dialog.offsetHeight-8))+'px';const outside=(event:PointerEvent)=>{if(!dialog.contains(event.target as Node)&&!anchor.contains(event.target as Node))dialog.close();};document.addEventListener('pointerdown',outside,true);dialog.onclose=()=>document.removeEventListener('pointerdown',outside,true);}else dialog.showModal();}
