function bulk(mode:string,ids:string[]){if(mode==='vendor')return vendorDialog(ids);if(mode==='pack')return packDialog(ids);if(mode==='delete'||mode==='restore'){modal(mode==='delete'?'Delete selected worksheet rows':'Restore original recommendations',`<p>${ids.length} selected rows${ids.some(id=>!visibleIds.includes(id))?' including hidden rows':''}. ${mode==='delete'?'Removes these products from this draft only. Undo restores them.':'Restores pinned original packs, vendor and pack size. Forecasting does not rerun.'}</p>`,()=>{const changes=ids.map(id=>({id,value:mode==='delete'?{...working(store.rows.get(id)!),removed:true}:working(store.rows.get(id)!.original)}));commit(mode==='delete'?'Delete rows':'Restore original advice',changes);rebuild();});return;}if(['set','increment','decrement'].includes(mode)){modal('Bulk whole-pack quantities',`<p>${ids.length} selected products × four stores. Hidden selections are included. This is one undo step.</p><label>${mode==='set'?'Set each store to':mode==='increment'?'Add to each store':'Subtract from each store'}<input type="number" id="bulk-amount" min="0" max="1000000" required></label>`,()=>commit('Bulk '+mode+' packs',store.quantityChanges(ids,mode as 'set'|'increment'|'decrement',integer($<HTMLInputElement>('#bulk-amount').value))));return;}throw Error('Choose a bulk action.');}
async function submissionPreview(){finishEditor();const vendors=[...store.groups.keys()].filter(id=>id&&store.totals.get(id)!.products);modal('Submit vendors · preview only',`<p>No purchasing request or purchase order can be submitted in this isolated phase. Select vendors to review the intended workflow.</p><table><thead><tr><th>Select</th><th>Vendor</th><th>Packs / internal estimate</th><th>Workflow</th></tr></thead><tbody>${vendors.map(id=>{const row=store.rows.get(store.groups.get(id)![0])!;return `<tr><td><input type="checkbox" data-submit-vendor="${id}" aria-label="Preview ${esc(store.vendorName(id))}"></td><td>${esc(store.vendorName(id))}</td><td>${esc(totalText(store.totals.get(id)!))}</td><td>${esc(row.offers[id]?.workflow??'Unresolved')}</td></tr>`;}).join('')}</tbody></table>`,async()=>{if(pending.length||batch||conflicted)throw Error('Save and resolve local edits before reviewing the current server version.');const ids=[...document.querySelectorAll<HTMLInputElement>('[data-submit-vendor]:checked')].map(i=>i.dataset.submitVendor!);const result=await api(`/api/worksheets/${snapshot.session.id}/submission-preview`,{expected_version:version,supplier_ids:ids});notify(`Previewed ${result.vendors.length} selected vendors. No requests, POs or commitments created.`);},'Preview selected',$('#submit-vendors'));}
async function addProduct(){finishEditor();if(pending.length||batch||conflicted){notify('Save or resolve the current edits before adding a catalog product. Ordinary quantity editing remains available.',true);return;}modal('Add product',`<label>Search catalog<input id="catalog-search" placeholder="Product name or SKU" autocomplete="off"></label><div id="catalog-results"></div>`);let generation=0;$('#catalog-search').oninput=async()=>{const seq=++generation;try{const result=await api('/api/catalog?search='+encodeURIComponent($<HTMLInputElement>('#catalog-search').value)+'&limit=30');if(seq!==generation)return;$('#catalog-results').innerHTML=result.rows.map((r:{variation_id:string;label:string;sku:string})=>`<button type="button" class="catalog-result" data-add="${r.variation_id}"><b>${esc(r.label)}</b><span>${esc(r.sku)}</span></button>`).join('');document.querySelectorAll<HTMLButtonElement>('[data-add]').forEach(button=>button.onclick=async()=>{try{const vid=button.dataset.add!,existing=[...store.rows.values()].find(r=>r.variation_id===vid);if(existing){if(existing.removed){commit('Restore manually added product',[{id:existing.id,value:{...working(existing),removed:false}}]);rebuild();}else notify('This product is already in the worksheet.');$<HTMLDialogElement>('#dialog').close();return;}const recoveryKey='v4-add:'+owner+':'+snapshot.session.id;const prior=JSON.parse(localStorage.getItem(recoveryKey)??'null');if(prior&&prior.variation_id!==vid)throw Error('Retry the pending product addition before selecting a different product.');const intent=prior??{command_id:crypto.randomUUID(),expected_version:version,variation_id:vid};localStorage.setItem(recoveryKey,JSON.stringify(intent));pendingAddition=true;saveStatus();const result=await api(`/api/worksheets/${snapshot.session.id}/add`,intent,10000);localStorage.removeItem(recoveryKey);pendingAddition=false;const old=snapshot.rows;version=result.version;const added=result.added[0] as Row;added.original=structuredClone(added);added.position=store.rows.size;snapshot={...snapshot,session:{...snapshot.session,version},rows:[...store.rows.values(),added]};const beforeGroups=Object.fromEntries(store.groups);const history=store.history,redo=store.redo;store=new Store(snapshot);for(const [sid,ids] of Object.entries(beforeGroups)){const list=store.groups.get(sid)!;store.groups.set(sid,[...ids,...list.filter(v=>!ids.includes(v))]);}store.history=history;store.redo=redo;store.sequence=Math.max(...commands.map(a=>a.seq),0);const action=store.action('Add product',[{id:added.id,value:working(added)}],[],[{id:added.id,value:{...working(added),removed:true}}]);action.status='ack';commands.push(action);await durable(()=>journal.snapshot(snapshot));await durable(()=>journal.command(action));await durable(()=>journal.meta(metadata()));view.order=Object.fromEntries(store.groups);view.orderSequence=store.sequence;rebuild();persistView();saveStatus();$<HTMLDialogElement>('#dialog').close();}catch(error){$('#dialog-error').textContent=(error as Error).message;}});}catch(error){$('#catalog-results').textContent=(error as Error).message;}};}
function freshDialog(){finishEditor();if(busy||pending.length||batch||conflicted||pendingAddition){notify('Save or resolve this draft before starting another. Quantity editing remains available.',true);return;}const freshCommand=crypto.randomUUID();modal('Start a fresh worksheet',`<p>The current draft remains available in Drafts. A new recommendation calculation runs only when explicitly selected.</p><label>Title<input id="fresh-title" value="Purchasing worksheet"></label><label>Starting point<select id="fresh-kind"><option value="empty">Empty manual worksheet</option><option value="calculate">Calculate from approved engine settings</option></select></label><label>Maximum evidence age (seconds; required for calculation)<input id="fresh-age" type="number" min="0"></label>`,async()=>{const calculate=$<HTMLSelectElement>('#fresh-kind').value==='calculate',age=$<HTMLInputElement>('#fresh-age').value;const result=await api('/api/worksheets',{command_id:freshCommand,title:$<HTMLInputElement>('#fresh-title').value,calculate,max_age_seconds:calculate?integer(age):undefined});location.hash=result.session.id;await openWorksheet(result);},'Start fresh');}
async function draftsDialog(after=''){finishEditor();const drafts=await api('/api/worksheets?after='+encodeURIComponent(after));modal('Unfinished drafts',`<p>Continue a saved draft without regenerating recommendations. Discarding retains audit records and affects only the uncommitted worksheet.</p><div class="draft-list">${drafts.rows.map((d:{id:string;title:string;version:number;updated_at:string})=>`<div><input type="checkbox" data-discard="${d.id}" data-version="${d.version}" aria-label="Discard ${esc(d.title)}"><button type="button" data-continue="${d.id}">${esc(d.title)}</button><small>Version ${d.version} · ${esc(d.updated_at.slice(0,10))}</small></div>`).join('')}</div><div class="toolbar"><button type="button" id="drafts-first">Newest drafts</button>${drafts.next_cursor?'<button type="button" id="drafts-next">Next 100 drafts</button>':''}</div>`,async()=>{const selected=[...document.querySelectorAll<HTMLInputElement>('[data-discard]:checked')];if(!selected.length)throw Error('Select unwanted drafts explicitly.');if(selected.some(i=>i.dataset.discard===snapshot.session.id)&&(pending.length||batch))throw Error('Export or resolve unsaved edits before discarding this draft.');await api('/api/worksheets/discard-selected',{command_id:crypto.randomUUID(),selections:selected.map(i=>({id:i.dataset.discard,expected_version:Number(i.dataset.version)}))});if(selected.some(i=>i.dataset.discard===snapshot.session.id)){localStorage.removeItem('v4-current:'+owner);location.hash='';location.reload();}else notify('Selected drafts discarded; audit records retained.');},'Discard selected drafts');$('#drafts-first').onclick=()=>{$<HTMLDialogElement>('#dialog').close();void draftsDialog();};$('#drafts-next')?.addEventListener('click',()=>{$<HTMLDialogElement>('#dialog').close();void draftsDialog(drafts.next_cursor);});document.querySelectorAll<HTMLButtonElement>('[data-continue]').forEach(b=>b.onclick=async()=>{if(busy||pending.length||batch||pendingAddition){$('#dialog-error').textContent='Save or export this draft before switching.';return;}$<HTMLDialogElement>('#dialog').close();location.hash=b.dataset.continue!;await openWorksheet(await api('/api/worksheets/'+b.dataset.continue));});}
async function openWorksheet(server:Snapshot){await metaTail;clearTimeout(saveTimer);clearTimeout(preferenceTimer);editor=undefined;range=undefined;focus=undefined;temporaryVendor=undefined;movedIds=[];pinnedMove=undefined;performance.mark('v4-state-start');let addRecoveryMessage='';let recoveredAddition:{command_id:string;added:Row[]}|undefined;pendingAddition=false;try{const key='v4-add:'+owner+':'+server.session.id;const intent=JSON.parse(localStorage.getItem(key)??'null');if(intent){pendingAddition=true;recoveredAddition=await api(`/api/worksheets/${server.session.id}/add`,intent,10000);localStorage.removeItem(key);pendingAddition=false;server=await api('/api/worksheets/'+server.session.id);addRecoveryMessage='Recovered the pending product addition without recalculating recommendations.';}}catch(error){addRecoveryMessage='Pending product addition retained: '+(error as Error).message+' Retry the same product from Add product after review.';}commands=[];pending=[];batch=undefined;conflicted=false;serverConflict=undefined;localFailure=false;nodes.forEach(n=>n.remove());nodes.clear();snapshot=server;try{localStorage.setItem('v4-current:'+owner,server.session.id);}catch{localFailure=true;}if(!server.session.stores||server.session.stores.length!==4)throw Error('Worksheet allocation identities require review.');stores=server.session.stores;version=server.session.version;store=new Store(server);journal=new Journal(owner,server.session.id);const prefs=await api('/api/worksheet-preferences');preferenceVersion=prefs.version;view={...initialView(),...prefs.value,query:'',order:prefs.value.session_id===server.session.id?prefs.value.order??{}:{},orderSequence:prefs.value.session_id===server.session.id?prefs.value.orderSequence??0:0,focus:prefs.value.session_id===server.session.id?prefs.value.focus:undefined,scroll:prefs.value.session_id===server.session.id?prefs.value.scroll:0,selected:[]};try{await journal.open();const saved=await journal.load();const syncPrefix='v4-command:'+owner+':'+server.session.id+':';const syncActions:Action[]=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i)!;if(key.startsWith(syncPrefix))syncActions.push(JSON.parse(localStorage.getItem(key)!));}saved.commands=[...new Map([...syncActions,...saved.commands].map(a=>[a.id,a])).values()].sort((a,b)=>a.seq-b.seq);if(saved.view)view={...view,...saved.view};if(saved.commands.length){commands=saved.commands;store.sequence=Math.max(...commands.map(c=>c.seq),0);for(const action of commands){if(action.status==='superseded')continue;if(action.kind==='DO'||action.kind==='REBASE'){store.history.push(structuredClone(action));store.redo=[];}else if(action.kind==='UNDO'){const prior=store.history.pop();if(prior){prior.defaults=structuredClone(action.inverseDefaults);store.redo.push(prior);}}else{const prior=store.redo.pop();if(prior){prior.inverseDefaults=structuredClone(action.inverseDefaults);store.history.push(prior);}}}pending=commands.filter(a=>a.status==='pending');batch=saved.batch;for(const action of pending){for(const c of action.changes)if(store.rows.has(c.id))store.set(c.id,c.value);for(const d of action.defaults)store.defaults.set(d.variation_id,{supplier_id:d.supplier_id,version:d.expected_version+1});}if(pending.length&&!batch&&(saved.ackVersion!==undefined?saved.ackVersion!==version:pending.some(a=>a.baseVersion===undefined||a.baseVersion!==version))){conflicted=true;serverConflict=server;}}if(recoveredAddition?.added.length){const added=recoveredAddition.added[0],target='ADD:'+recoveredAddition.command_id;if(store.rows.has(added.id)&&!commands.some(a=>a.target===target)){const current=working(store.rows.get(added.id)!);const action=store.action('Recovered product addition',[{id:added.id,value:current}],[],[{id:added.id,value:{...current,removed:true}}],'DO',target);action.status='ack';commands.push(action);await journal.command(action);}}for(const action of syncActions){await journal.command(action);localStorage.removeItem(syncPrefix+action.id);}await journal.snapshot(server);}catch(error){localFailure=true;}
 for(const [sid,ids] of Object.entries(view.order??{})){if(store.groups.has(sid)){const current=store.groups.get(sid)!;store.groups.set(sid,[...ids.filter(id=>current.includes(id)),...current.filter(id=>!ids.includes(id))]);}}if((view.orderSequence??0)<Math.max(...pending.map(a=>a.seq),0))for(const action of pending)store.restorePositions(action.afterPositions);store.selected=new Set((view.selected??[]).filter(id=>store.rows.has(id)));focus=view.focus;lastSort=view.sort?.key??'name';sortDirection=view.sort?.direction??1;let recovered:Action|undefined;try{const key='v4-editor:'+owner+':'+server.session.id;const envelope=JSON.parse(localStorage.getItem(key)??'null');if(envelope&&store.rows.has(envelope.id)){const current=working(store.rows.get(envelope.id)!);if(JSON.stringify(current)!==JSON.stringify(envelope.value)){if(!pending.length&&JSON.stringify(current)!==JSON.stringify(envelope.before)){conflicted=true;serverConflict=server;}recovered=store.action('Recovered active cell edit',[{id:envelope.id,value:envelope.value}]);commands.push(recovered);pending.push(recovered);await durable(()=>journal.command(recovered!));}localStorage.removeItem(key);}}catch{localFailure=true;}try{view.widths=JSON.parse(localStorage.getItem('v4-widths:'+owner)??'{}');}catch{view.widths={};}shell();void loadInventory();if(addRecoveryMessage)notify(addRecoveryMessage,true);$('#viewport').scrollTop=view.scroll??0;renderWindow();if(conflicted){$('#review-conflict').hidden=false;showConflict();}else if(pending.length||batch)schedule(0);if(localFailure)notify('Local recovery is unavailable. Export edits before closing this window.',true);requestAnimationFrame(()=>requestAnimationFrame(()=>performance.mark('v4-first-grid-frame')));}
async function boot(){try{const context=await api('/api/context');owner=context.owner_id;stores=context.stores;const drafts=await api('/api/worksheets');let id=location.hash.slice(1);try{id=id||localStorage.getItem('v4-current:'+owner)||'';}catch{}let recovered:Snapshot|undefined;if(id){try{const candidate=await api('/api/worksheets/'+id);if(candidate.session.state==='EDITABLE')recovered=candidate;}catch(error){if(![404,422].includes((error as Error&{status?:number}).status??0))throw error;}}if(!recovered&&drafts.rows[0])recovered=await api('/api/worksheets/'+drafts.rows[0].id);if(recovered)await openWorksheet(recovered);else{const emptyDraft=await api('/api/worksheets',{command_id:crypto.randomUUID(),title:'Purchasing worksheet',calculate:false});location.hash=emptyDraft.session.id;await openWorksheet(emptyDraft);freshDialog();}}catch(error){root.innerHTML='<div class="startup-error"><h1>Purchasing workspace</h1><p>'+esc((error as Error).message)+'</p><a href="/login">Owner sign in</a></div>';}}
void boot();

function columnTitle(key:string,label:string){return label+(key.startsWith('inventory')?' · read-only individual inventory units; unknown or stale values are not zero':key.startsWith('store')||key==='total'?' · purchasing packs':'');}
function columnMinimum(key:string):number{if(key==='selection')return 30;if(key==='name')return 100;if(key==='variation')return 70;if(key.startsWith('store'))return 56;if(key==='total')return 76;if(key==='pack_size')return 52;if(key.startsWith('inventory'))return Math.max(44,inventoryMinimums[key]??44);return Math.max(72,numericMinimums[key]??72);}
let inventoryMinimums:Record<string,number>={};
function saveWidths(){try{localStorage.setItem('v4-widths:'+owner,JSON.stringify(view.widths));persistView(false);}catch{notify('Column widths could not be retained in this browser.',true);}}
function paintInventory(node:HTMLElement,row:Row){for(const cell of node.querySelectorAll<HTMLElement>('[data-inventory]')){const i=Number(cell.dataset.inventory),e=row.inventory?.[i];cell.textContent=inventoryValue(e);cell.title=stores[i].name+' on hand · individual units · '+(e?.state==='KNOWN'?e.value+' units':e?.reason.replaceAll('_',' ').toLowerCase()??'inventory not loaded')+(e?.observed_at?' · observed '+e.observed_at:'')+(inventoryCutoff?' · snapshot '+inventoryCutoff:'');cell.classList.toggle('unqualified',e?.state!=='KNOWN');}const total=inventoryTotal(row.inventory),cell=node.querySelector<HTMLElement>('.inventory-total')!;cell.textContent=total.complete?total.text:'—';cell.title=total.complete?'Total on hand · individual units · all four stores confirmed':'Total on hand incomplete: one or more stores have unknown, stale or unavailable inventory. No complete total is asserted.';cell.classList.toggle('unqualified',!total.complete);}
async function loadInventory(){const sid=snapshot.session.id;let age:string|null=null;try{age=localStorage.getItem('v4-inventory-age:'+owner);}catch{}try{const result=await api('/api/worksheets/'+sid+'/inventory'+(age!==null?'?max_age_seconds='+encodeURIComponent(age):''));if(snapshot.session.id!==sid)return;inventoryCutoff=result.as_of;inventoryMinimums={};for(const [id,values] of Object.entries(result.rows)){const row=store.rows.get(id);if(!row)continue;row.inventory=values as Inventory[];row.inventory.forEach((e,i)=>{if(e.state==='KNOWN'&&e.value!==null)inventoryMinimums['inventory'+i]=Math.max(inventoryMinimums['inventory'+i]??36,inventoryValue(e).length*7+12);});const total=inventoryTotal(row.inventory);if(total.complete)inventoryMinimums.inventoryTotal=Math.max(inventoryMinimums.inventoryTotal??36,total.text.length*7+12);}for(const [key,node] of nodes)if(key.startsWith('row:'))paintInventory(node,store.rows.get(key.slice(4))!);headers();$('#inventory-settings').title='Read-only individual-unit snapshot '+inventoryCutoff+(age===null?' · freshness limit required':' · maximum observation age '+age+' seconds');}catch(error){if(snapshot.session.id===sid)notify('Inventory unavailable. Ordering edits are retained. '+(error as Error).message,true);}}
function inventoryDialog(){finishEditor();let age='';try{age=localStorage.getItem('v4-inventory-age:'+owner)??'';}catch{}modal('Inventory evidence',`<p>On hand is read-only, in individual inventory units. Order columns are purchasing packs. Choose an explicit maximum observation age; no freshness policy is assumed. Loading this snapshot does not refresh inventory, forecast or post adjustments.</p><label>Maximum observation age (seconds)<input id="inventory-age" type="number" min="0" max="315360000" value="${esc(age)}" placeholder="Explicit owner choice required"></label><p class="muted">${esc(inventoryCutoff?'Current snapshot: '+inventoryCutoff:'No inventory snapshot loaded')}</p>`,()=>{const value=$<HTMLInputElement>('#inventory-age').value;if(!/^\d+$/.test(value)||Number(value)>315360000)throw Error('Enter an explicit nonnegative inventory age in seconds.');localStorage.setItem('v4-inventory-age:'+owner,String(Number(value)));void loadInventory();},'Load read-only snapshot');}
