export type Packs=(number|null)[];
export type Offer={supplier_id:string;name:string;pack_size:number|null;expected_unit_cost:string|null;vendor_sku:string|null;workflow:string};
export type Working={packs:Packs;touched:boolean[];supplier_id:string|null;pack_size:number|null;removed:boolean};
export type Inventory={state:'KNOWN'|'UNKNOWN'|'UNAVAILABLE';value:string|null;reason:string;source:string;observed_at?:string|null;references?:string[]};
export type Row=Working&{inventory?:Inventory[];id:string;variation_id:string;name:string;variation:string;sku:string|null;gtin:string;categories:string[];offers:Record<string,Offer>;unit_cost:string|null;vendor_sku:string|null;assignment_version:number;default_supplier_id?:string|null;advice_units:(string|null)[];policy:string[];warnings:string[];position:number;original:Row};
export type Change={id:string;value:Working};
export type DefaultChange={variation_id:string;supplier_id:string|null;expected_version:number};
export type Action={id:string;seq:number;kind:'DO'|'UNDO'|'REDO'|'REBASE';label:string;changes:Change[];inverse:Change[];defaults:DefaultChange[];inverseDefaults:DefaultChange[];status:'pending'|'ack'|'superseded';target?:string;baseVersion?:number;positions?:{id:string;vendor:string;index:number}[];afterPositions?:{id:string;vendor:string;index:number}[]};
export type Snapshot={session:{id:string;version:number;state:string;title:string;owner_id:number;generation_id:string|null;stores?:{id:number;name:string}[]};rows:Row[]};
export type Money={n:bigint;scale:number};
export type Total={products:number;packs:number;cost:Money;unknown:number;unresolved:number};
export const empty=():Total=>({products:0,packs:0,cost:{n:0n,scale:0},unknown:0,unresolved:0});
export const working=(r:Working):Working=>({packs:[...r.packs],touched:[...r.touched],supplier_id:r.supplier_id,pack_size:r.pack_size,removed:r.removed});
export function integer(text:string):number{if(!/^\d+$/.test(text.trim()))throw Error('Enter a nonnegative whole number of packs.');const value=Number(text);if(!Number.isSafeInteger(value)||value>1_000_000)throw Error('Pack quantities must be between 0 and 1,000,000.');return value;}
export function decimal(text:string):Money{const match=/^(\d+)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/.exec(text);if(!match)throw Error('Expected cost must be an exact nonnegative decimal.');const exponent=Number(match[3]??0);if(!Number.isSafeInteger(exponent)||Math.abs(exponent)>10000)throw Error('Expected cost magnitude exceeds the supported exact display format; review cost evidence.');const fraction=match[2]??'';let n=BigInt(match[1]+fraction),scale=fraction.length-exponent;if(scale<0){n*=10n**BigInt(-scale);scale=0;}return {n,scale};}
export function plus(a:Money,b:Money,sign=1):Money{const scale=Math.max(a.scale,b.scale);return {n:a.n*10n**BigInt(scale-a.scale)+BigInt(sign)*b.n*10n**BigInt(scale-b.scale),scale};}
export function times(a:Money,n:bigint):Money{return {n:a.n*n,scale:a.scale};}
export function money(value:Money):string{const divisor=value.scale>2?10n**BigInt(value.scale-2):1n;const cents=value.scale>2?(value.n+divisor/2n)/divisor:value.n*10n**BigInt(2-value.scale);return '$'+(cents/100n).toLocaleString('en-US')+'.'+String(cents%100n).padStart(2,'0');}
export function moneyExact(value:Money):string{const scale=Math.max(2,value.scale);const n=value.n*10n**BigInt(scale-value.scale);const divisor=10n**BigInt(scale);const whole=n/divisor;let fraction=String(n%divisor).padStart(scale,'0');while(fraction.length>2&&fraction.endsWith('0'))fraction=fraction.slice(0,-1);return '$'+whole.toLocaleString('en-US')+'.'+fraction;}
export function repack(units:string|null,size:number|null):number|null{if(units===null||size===null)return null;const [ns,ds='1']=units.includes('/')?units.split('/'):decimalRatio(units);const n=BigInt(ns),d=BigInt(ds)*BigInt(size);if(n<=0n)return 0;return Number(((n*2n+d)/(d*2n))||1n);}
function decimalRatio(s:string):string[]{const [w,f='']=s.split('.');return [w+f,'1'+'0'.repeat(f.length)];}
export function rowTotal(r:Row):Total{if(r.removed)return empty();const packs=r.packs.reduce<number>((a,v)=>a+(v??0),0),offer=r.supplier_id?r.offers[r.supplier_id]:null,cost=offer?.expected_unit_cost;return {products:1,packs,cost:cost!==null&&cost!==undefined&&r.pack_size!==null?times(decimal(cost),BigInt(r.pack_size)*BigInt(packs)):{n:0n,scale:0},unknown:packs>0&&(cost==null||r.pack_size===null)?1:0,unresolved:r.packs.filter(v=>v===null).length};}
function aggregate(target:Total,value:Total,sign:number){target.products+=sign*value.products;target.packs+=sign*value.packs;target.cost=plus(target.cost,value.cost,sign);target.unknown+=sign*value.unknown;target.unresolved+=sign*value.unresolved;}
export type View={query:string;vendors:string[]|null;collapsed:string[];order:Record<string,string[]>;columns:Record<string,boolean>;widths:Record<string,number>;showCosts:boolean;focus?:{id:string;col:number};scroll?:number;selected?:string[];paged?:boolean;page?:number;orderSequence?:number;sort?:{key:string;direction:number}};
export const initialView=():View=>({query:'',vendors:null,collapsed:[],order:{},columns:{sku:false,vendor_sku:false,category:false,unit_cost:true,pack_cost:true,extended:true},widths:{},showCosts:true});
export class Store{
 defaults=new Map<string,{supplier_id:string|null;version:number}>();
 rows=new Map<string,Row>();groups=new Map<string,string[]>();totals=new Map<string,Total>();total=empty();selected=new Set<string>();history:Action[]=[];redo:Action[]=[];sequence=0;
 constructor(snapshot:Snapshot){for(const r of snapshot.rows){this.defaults.set(r.variation_id,{supplier_id:r.default_supplier_id===undefined?r.supplier_id:r.default_supplier_id,version:r.assignment_version});this.rows.set(r.id,structuredClone(r));const k=r.supplier_id??'';if(!this.groups.has(k))this.groups.set(k,[]);this.groups.get(k)!.push(r.id);const total=rowTotal(r);if(!this.totals.has(k))this.totals.set(k,empty());aggregate(this.totals.get(k)!,total,1);aggregate(this.total,total,1);}for(const list of this.groups.values())list.sort((a,b)=>this.compare(a,b,'name',1));}
 compare(a:string,b:string,key:string,direction:number){const x=this.rows.get(a)!,y=this.rows.get(b)!;let av:unknown,bv:unknown;if(key.startsWith('store')){const i=Number(key.slice(5));av=x.packs[i]??-1;bv=y.packs[i]??-1;}else if(key==='total'){av=rowTotal(x).packs;bv=rowTotal(y).packs;}else if(['unit_cost','pack_cost','extended'].includes(key)){const value=(r:Row):Money|undefined=>{const offer=r.supplier_id?r.offers[r.supplier_id]:undefined;if(key==='extended'){const total=rowTotal(r);return total.unknown||total.unresolved?undefined:total.cost;}if(offer?.expected_unit_cost==null||key==='pack_cost'&&r.pack_size===null)return undefined;return times(decimal(offer.expected_unit_cost),BigInt(key==='pack_cost'?r.pack_size!:1));};av=value(x);bv=value(y);if(av===undefined||bv===undefined)return av===bv?x.name.localeCompare(y.name)||a.localeCompare(b):av===undefined?1:-1;}else{av=(x as unknown as Record<string,unknown>)[key];bv=(y as unknown as Record<string,unknown>)[key];}const c=typeof av==='number'&&typeof bv==='number'?av-bv:typeof av==='object'&&av!==null&&typeof bv==='object'&&bv!==null?Math.sign(Number(plus(av as Money,bv as Money,-1).n)):String(av??'').localeCompare(String(bv??''),undefined,{numeric:true});return direction*c||x.name.localeCompare(y.name)||x.variation.localeCompare(y.variation)||a.localeCompare(b);}
 sort(key:string,direction:number){for(const ids of this.groups.values())ids.sort((a,b)=>this.compare(a,b,key,direction));}
 set(id:string,value:Working){const row=this.rows.get(id);if(!row)throw Error('Unknown worksheet row.');const oldKey=row.supplier_id??'',newKey=value.supplier_id??'';const before=rowTotal(row);aggregate(this.total,before,-1);aggregate(this.totals.get(oldKey)!,before,-1);Object.assign(row,working(value));const offer=row.supplier_id?row.offers[row.supplier_id]:undefined;row.unit_cost=offer?.expected_unit_cost??null;row.vendor_sku=offer?.vendor_sku??null;const after=rowTotal(row);if(!this.totals.has(newKey))this.totals.set(newKey,empty());aggregate(this.total,after,1);aggregate(this.totals.get(newKey)!,after,1);if(newKey!==oldKey){this.groups.set(oldKey,this.groups.get(oldKey)!.filter(v=>v!==id));if(!this.groups.has(newKey))this.groups.set(newKey,[]);this.groups.get(newKey)!.push(id);}}
 action(label:string,changes:Change[],defaults:DefaultChange[]=[],before?:Change[],kind:Action['kind']='DO',target?:string):Action{const moving=changes.filter(c=>(this.rows.get(c.id)!.supplier_id??'')!==(c.value.supplier_id??''));const positions=moving.map(c=>{const vendor=this.rows.get(c.id)!.supplier_id??'';return {id:c.id,vendor,index:this.groups.get(vendor)!.indexOf(c.id)};});const inverse=before??changes.map(v=>({id:v.id,value:working(this.rows.get(v.id)!)}));for(const d of defaults)if(d.expected_version!==(this.defaults.get(d.variation_id)?.version??0))throw Error('The default supplier changed after this action. Review the newer policy before undo or redo.');const inverseDefaults=defaults.map(d=>{const old=this.defaults.get(d.variation_id)??{supplier_id:null,version:0};if(d.expected_version!==old.version)throw Error('The default supplier changed after this action. Review the newer policy before undo or redo.');this.defaults.set(d.variation_id,{supplier_id:d.supplier_id,version:old.version+1});return {variation_id:d.variation_id,supplier_id:old.supplier_id,expected_version:old.version+1};});for(const c of changes)this.set(c.id,c.value);const action:Action={id:crypto.randomUUID(),seq:++this.sequence,kind,label,changes:structuredClone(changes),inverse:structuredClone(inverse),defaults:structuredClone(defaults),inverseDefaults,status:'pending',target,positions,afterPositions:moving.map(c=>{const vendor=this.rows.get(c.id)!.supplier_id??'';return {id:c.id,vendor,index:this.groups.get(vendor)!.indexOf(c.id)};})};if(kind==='DO'||kind==='REBASE'){this.history.push(structuredClone(action));this.redo=[];}return action;}
 undo():Action|null{const prior=this.history.at(-1);if(!prior)return null;for(const c of prior.changes){const row=this.rows.get(c.id);if(!row||JSON.stringify(working(row))!==JSON.stringify(c.value))throw Error('This row changed after the recorded action. Review both versions before undoing it.');}const action=this.action('Undo '+prior.label,prior.inverse,structuredClone(prior.inverseDefaults),undefined,'UNDO',prior.id);this.restorePositions(prior.positions);action.afterPositions=prior.positions;this.history.pop();prior.defaults=structuredClone(action.inverseDefaults);this.redo.push(prior);return action;}
 redoAction():Action|null{const prior=this.redo.at(-1);if(!prior)return null;for(const c of prior.inverse){const row=this.rows.get(c.id);if(!row||JSON.stringify(working(row))!==JSON.stringify(c.value))throw Error('This row changed after undo. Review both versions before redoing it.');}const action=this.action('Redo '+prior.label,prior.changes,structuredClone(prior.defaults),undefined,'REDO',prior.id);this.restorePositions(prior.afterPositions);action.afterPositions=prior.afterPositions;this.redo.pop();prior.inverseDefaults=structuredClone(action.inverseDefaults);this.history.push(prior);return action;}
 restorePositions(positions:Action['positions']){if(!positions?.length)return;const grouped=new Map<string,typeof positions>();for(const position of positions){if((this.rows.get(position.id)?.supplier_id??'')!==position.vendor)continue;if(!grouped.has(position.vendor))grouped.set(position.vendor,[]);grouped.get(position.vendor)!.push(position);}for(const [vendor,values] of grouped){const moved=new Set(values.map(p=>p.id));const list=(this.groups.get(vendor)??[]).filter(id=>!moved.has(id));for(const position of values.sort((a,b)=>a.index-b.index))list.splice(Math.min(position.index,list.length),0,position.id);this.groups.set(vendor,list);}}
 packChanges(ids:string[],size:number):Change[]{if(!Number.isInteger(size)||size<1||size>1_000_000)throw Error('Enter a positive whole pack size.');return ids.map(id=>{const row=this.rows.get(id)!,value=working(row);value.pack_size=size;value.packs=value.packs.map((p,i)=>value.touched[i]?p:repack(row.advice_units[i],size));return {id,value};});}
 vendorChanges(ids:string[],supplier:string):Change[]{return ids.map(id=>{const row=this.rows.get(id)!,offer=row.offers[supplier];if(!offer)throw Error(`${row.name} has no approved offer from this vendor. Review it in Supplier management first.`);const value=working(row);value.supplier_id=supplier;value.pack_size=offer.pack_size;value.packs=value.packs.map((p,i)=>value.touched[i]?p:repack(row.advice_units[i],value.pack_size));return {id,value};});}
 quantityChanges(ids:string[],mode:'set'|'increment'|'decrement',amount:number):Change[]{return ids.map(id=>{const value=working(this.rows.get(id)!);value.packs=value.packs.map(p=>{if(mode!=='set'&&p===null)throw Error('Resolve unknown quantities explicitly before incrementing or decrementing.');return mode==='set'?amount:mode==='increment'?(p!+amount):Math.max(0,p!-amount);});value.touched=[true,true,true,true];if(value.packs.some(v=>v!>1_000_000))throw Error('Pack quantity exceeds the qualified limit.');return {id,value};});}
 paste(ids:string[],start:number,col:number,text:string):Change[]{const lines=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(l=>l.split('\t'));if(!lines.length||lines.some(l=>l.length!==lines[0].length)||col+lines[0].length>4||start+lines.length>ids.length)throw Error('Paste a rectangular range within the four store columns and existing displayed rows.');const parsed=lines.map(l=>l.map(integer));return parsed.map((line,i)=>{const id=ids[start+i],value=working(this.rows.get(id)!);line.forEach((v,j)=>{value.packs[col+j]=v;value.touched[col+j]=true;});return {id,value};});}
 visible(view:View):{groups:{id:string;ids:string[]}[];ids:string[];vendorIds:string[]}{const tokens=view.query.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean),search=!!tokens.length;const groups:{id:string;ids:string[]}[]=[];const ids:string[]=[];for(const [vendor,list] of this.groups){if(!search&&view.vendors!==null&&!view.vendors.includes(vendor))continue;const matches=list.filter(id=>{const row=this.rows.get(id)!;if(row.removed)return false;if(!search)return true;const offer=row.supplier_id?row.offers[row.supplier_id]:null;const name=(row.name+' '+row.variation).toLocaleLowerCase();const all=(name+' '+(row.sku??'')+' '+(offer?.vendor_sku??'')+' '+row.gtin).toLocaleLowerCase();return tokens.every(t=>all.includes(t));});if(!matches.length)continue;if(search){const rank=(id:string)=>{const r=this.rows.get(id)!;const name=(r.name+' '+r.variation).toLocaleLowerCase();return tokens.every(t=>name.includes(t))?0:1;};matches.sort((a,b)=>rank(a)-rank(b));}const expanded=search||!view.collapsed.includes(vendor);groups.push({id:vendor,ids:expanded?matches:[]});if(expanded)ids.push(...matches);}groups.sort((a,b)=>this.vendorName(a.id).localeCompare(this.vendorName(b.id)));const ordered=groups.flatMap(g=>g.ids);return {groups,ids:ordered,vendorIds:groups.map(g=>g.id)};}
 vendorName(id:string){if(!id)return 'Supplier unresolved';for(const rowId of this.groups.get(id)??[]){const offer=this.rows.get(rowId)?.offers[id];if(offer)return offer.name;}return id;}
}

export function unitText(value:string):string{return value.includes('.')?value.replace(/0+$/,'').replace(/\.$/,''):value;}
export function inventoryValue(e:Inventory|undefined):string{return e?.state==='KNOWN'&&e.value!==null?unitText(e.value):e?.reason.includes('STALE')?'Stale':'—';}
export function inventoryTotal(values:Inventory[]|undefined):{text:string;complete:boolean}{if(!values||values.length!==4||values.some(e=>e.state!=='KNOWN'||e.value===null))return {text:'Incomplete',complete:false};let sum:Money={n:0n,scale:0};for(const e of values){const value=e.value!;sum=plus(sum,decimal(value.startsWith('-')?value.slice(1):value),value.startsWith('-')?-1:1);}const negative=sum.n<0n;const digits=(negative?-sum.n:sum.n).toString().padStart(sum.scale+1,'0');return {text:unitText((negative?'-':'')+(sum.scale?digits.slice(0,-sum.scale)+'.'+digits.slice(-sum.scale):digits)),complete:true};}
